#include <iostream>
#include <sstream>
#include <stdexcept>

struct Token {
    char clase;
    int valor;
};

Token leer_token(std::istringstream& entrada) {
    char actual = '?';

    while (entrada.get(actual)) {
        if (actual == ' ' || actual == '\t' || actual == '\n') {
            continue;
        }

        if (actual >= '0' && actual <= '9') {
            return Token{'n', actual - '0'};
        }

        if (actual == '+' || actual == '-' || actual == '*'
                || actual == '/' || actual == '(' || actual == ')'
                || actual == ';') {
            return Token{actual, 0};
        }

        throw std::runtime_error("Caracter no admitido");
    }

    if (entrada.bad() || !entrada.eof()) {
        throw std::runtime_error("Fallo del flujo");
    }

    return Token{'f', 0};
}

int main() {
    std::istringstream entrada{"4+2;"};

    try {
        const Token primero = leer_token(entrada);
        const Token segundo = leer_token(entrada);
        std::cout << primero.clase << ":" << primero.valor << "\n";
        std::cout << segundo.clase;
    } catch (const std::runtime_error& error) {
        std::cout << "Error: " << error.what();
    }

    return 0;
}

